-- =============================================================================
-- V8__webauthn_relying_party.sql
-- The Wallet Unit Service becomes a WebAuthn Relying Party (EUD-308, feature EUD-8):
--   - wallet_user.webauthn_user_handle: random 32-byte user handle generated by
--     the service (never derived from the email). Backfilled for existing accounts.
--   - user_passkey: full WebAuthn credential record (public key, counter, backup
--     flags...). credential_id becomes unique in the tenant, not only per account.
--   - refresh_token: a refresh token family is a session (session_id,
--     session_started_at); every session is opened by a verified passkey.
--   - webauthn_ceremony / registration_ticket: single-use, 5-minute challenges and
--     registration tickets, consumed atomically.
--
-- The current passkeys have no public key and cannot be verified, so they are
-- deleted together with every refresh token: users sign in again with their
-- email and create a new passkey (design.md §6).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Existing sessions and passkeys are dropped (refresh_token references user_passkey)
-- -----------------------------------------------------------------------------
DELETE FROM refresh_token;
DELETE FROM user_passkey;

-- -----------------------------------------------------------------------------
-- wallet_user: WebAuthn user handle (32 random bytes)
-- gen_random_uuid() uses a CSPRNG; two UUIDs give 32 bytes (244 random bits)
-- without requiring pgcrypto.
-- -----------------------------------------------------------------------------
ALTER TABLE wallet_user ADD COLUMN webauthn_user_handle BYTEA;

UPDATE wallet_user
   SET webauthn_user_handle = uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid());

ALTER TABLE wallet_user ALTER COLUMN webauthn_user_handle SET NOT NULL;
-- The service always generates the handle; the default is only a safety net for rows written
-- outside it (manual provisioning, fixtures), with the same random source as the backfill.
ALTER TABLE wallet_user
    ALTER COLUMN webauthn_user_handle SET DEFAULT (uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid()));
ALTER TABLE wallet_user
    ADD CONSTRAINT uq_wallet_user_webauthn_user_handle UNIQUE (webauthn_user_handle);
ALTER TABLE wallet_user
    ADD CONSTRAINT chk_wallet_user_webauthn_user_handle_len CHECK (octet_length(webauthn_user_handle) = 32);

-- -----------------------------------------------------------------------------
-- user_passkey: WebAuthn credential record
-- -----------------------------------------------------------------------------
ALTER TABLE user_passkey DROP CONSTRAINT IF EXISTS user_passkey_user_id_credential_id_key;

ALTER TABLE user_passkey
    ADD COLUMN attested_credential_data BYTEA       NOT NULL,
    ADD COLUMN aaguid                   UUID,
    ADD COLUMN sign_count               BIGINT      NOT NULL,
    ADD COLUMN transports               VARCHAR(128),
    ADD COLUMN uv_initialized           BOOLEAN     NOT NULL,
    ADD COLUMN backup_eligible          BOOLEAN     NOT NULL,
    ADD COLUMN backup_state             BOOLEAN     NOT NULL,
    ADD COLUMN attestation_format       VARCHAR(32),
    ADD COLUMN prf_enabled              BOOLEAN     NOT NULL;

ALTER TABLE user_passkey
    ADD CONSTRAINT uq_user_passkey_credential_id UNIQUE (credential_id);
ALTER TABLE user_passkey
    ADD CONSTRAINT chk_user_passkey_sign_count CHECK (sign_count >= 0);

-- -----------------------------------------------------------------------------
-- refresh_token: token family = session; passkey mandatory.
-- passkey_id becomes NOT NULL, so the FK switches from SET NULL to CASCADE:
-- deleting a passkey removes its (already revoked) tokens.
-- -----------------------------------------------------------------------------
ALTER TABLE refresh_token
    ADD COLUMN session_id         UUID        NOT NULL,
    ADD COLUMN session_started_at TIMESTAMPTZ NOT NULL;

ALTER TABLE refresh_token DROP CONSTRAINT IF EXISTS refresh_token_passkey_id_fkey;
ALTER TABLE refresh_token ALTER COLUMN passkey_id SET NOT NULL;
ALTER TABLE refresh_token
    ADD CONSTRAINT fk_refresh_token_passkey
        FOREIGN KEY (passkey_id) REFERENCES user_passkey (id) ON DELETE CASCADE;

CREATE INDEX idx_refresh_token_session_id ON refresh_token (session_id);
CREATE INDEX idx_refresh_token_user_id ON refresh_token (user_id);

-- -----------------------------------------------------------------------------
-- email_verification: a code replaced by a newer one is answered as expired_code
-- -----------------------------------------------------------------------------
ALTER TABLE email_verification ADD COLUMN replaced_at TIMESTAMPTZ;

-- -----------------------------------------------------------------------------
-- webauthn_ceremony: challenge issued by the service, single use, 5 minutes
-- -----------------------------------------------------------------------------
CREATE TABLE webauthn_ceremony (
    id          UUID        PRIMARY KEY,
    type        VARCHAR(16) NOT NULL,
    challenge   BYTEA       NOT NULL,
    user_id     UUID        REFERENCES wallet_user (id) ON DELETE CASCADE,
    expires_at  TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_webauthn_ceremony_type CHECK (type IN ('REGISTRATION', 'AUTHENTICATION')),
    CONSTRAINT chk_webauthn_ceremony_challenge_len CHECK (octet_length(challenge) = 32)
);

CREATE INDEX idx_webauthn_ceremony_created_at ON webauthn_ceremony (created_at);

-- -----------------------------------------------------------------------------
-- registration_ticket: proof of email possession, single account, single use,
-- 5 minutes. Only the SHA-256 of the ticket is stored.
-- -----------------------------------------------------------------------------
CREATE TABLE registration_ticket (
    id          UUID        PRIMARY KEY,
    user_id     UUID        NOT NULL REFERENCES wallet_user (id) ON DELETE CASCADE,
    token_hash  VARCHAR(64) NOT NULL,
    expires_at  TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT uq_registration_ticket_token_hash UNIQUE (token_hash)
);

CREATE INDEX idx_registration_ticket_created_at ON registration_ticket (created_at);

REVOKE ALL ON webauthn_ceremony FROM PUBLIC;
REVOKE ALL ON registration_ticket FROM PUBLIC;

DO $$
BEGIN
    GRANT SELECT, INSERT, UPDATE, DELETE ON webauthn_ceremony TO ebw_app_role;
    GRANT SELECT, INSERT, UPDATE, DELETE ON registration_ticket TO ebw_app_role;
EXCEPTION
    WHEN undefined_object THEN NULL;
END
$$;
